"""Internal stream sorting helper."""
import hashlib
from typing import List
from event_packet import EventPacket

def order_packets(packets: List[EventPacket]) -> List[EventPacket]:
    # H07: Event Priority Queue Ordering and Deterministic SHA-256 Tie-Breaking
    # Events with identical priority score (severity) must be ordered deterministically
    # by payload SHA-256 digest in ascending lexicographical order.
    return sorted(packets, key=lambda p: (
        -p.severity,
        hashlib.sha256(p.payload.encode('utf-8')).hexdigest()
    ))

def get_max_severity(packets: List[EventPacket]) -> int:
    return max((p.severity for p in packets), default=0)

def count_critical_packets(packets: List[EventPacket]) -> int:
    return sum(1 for p in packets if p.is_critical())
